    b4(cfg, "hover", "--x", str(cx), "--y", str(cy))
    nap(0.8)
    return read_slider(cfg)


def confirm(cfg, expected):
    first = sync(cfg)
    if not reading_ok(first, expected):
        return None
    second = sync(cfg)
    return second if consistent(first, second, expected) else None


def find_pause(cfg):
    matches = find_matches(cfg, title="Pause", role="button", limit=3)
    return first_where(functools.partial(is_key_button, "Pause"), matches)


def press_target(cfg, target):
    if target is None:
        return Result(-1, "", "pause button not found")
    return b4(cfg, "press", "--path", target["path"], "--expect-description",
              target.get("description") or "Pause")


def pause_video(cfg, deadline):
    nap_until(deadline - 1.5)
    target = find_pause(cfg)
    nap_until(deadline)
    first = press_target(cfg, target)
    return first if first.code == 0 else press_target(cfg, find_pause(cfg))


# ----------------------------------------------------------------------------
# Per-song workflow
# ----------------------------------------------------------------------------


def search_candidates(cfg, song):
    specs = (dict(title="Search", role="combobox", limit=4), dict(title="Search", role="button", limit=8))
    box_ms, btn_ms = concurrently(lambda spec: find_matches(cfg, **spec), specs)
    button = first_where(lambda m: m.get("title") == "Search" and role_is(m, "button"), btn_ms)
    box = first_where(lambda m: m.get("title") == "Search" and role_is(m, "combobox"), box_ms)
    if button is None:
        return (), "search button not found"
    box_path = box["path"] if box else derive_box(button["path"])
    typed = b4(cfg, "set-value", "--path", box_path, "--value", song.query, "--expect-description", "Search")
    if typed.code != 0:
        return (), "set-value failed: " + typed.err.strip()[:120]
    sent = b4(cfg, "press", "--path", button["path"], "--expect-description", "Search")
    if sent.code != 0:
        return (), "search press failed: " + sent.err.strip()[:120]
    nap(2.5)
    found = poll(lambda: rank_results(
        song.query, find_matches(cfg, role="link", identifier="video-title", limit=12)), 4, 1.5)
    return (found or ()), ("" if found else "no suitable result")


def acquire_step(cfg, song, acc, i):
    if acc.done:
        return acc
    pause, skip, play = concurrently(
        lambda t: find_matches(cfg, title=t, role="button", limit=6), ("Pause", "Skip", "Play"))
    state, target = classify(pause, skip, play)
    if state == "playing":
        return Acq(True, acc.ad_seen, now())
    if state == "ad":
        if not acc.ad_seen:
            emit(cfg, song, "ad_seen")
        b4(cfg, "press", "--path", target["path"], "--expect-description", target.get("description") or "Skip")
        nap(1.5)
        return acc._replace(ad_seen=True)
    if state == "paused" and i >= 3:
        b4(cfg, "press", "--path", target["path"], "--expect-description", target.get("description") or "Play")
    nap(1.5 if state == "paused" else 2.0)
    return acc


def play_candidate(cfg, song, cand):
    opened = b4(cfg, "press", "--path", cand.path, "--expect-description", cand.description)
    if opened.code != 0:
        return Outcome(False, "open failed (%d): %s" % (opened.code, opened.err.strip()[:120]), True)
    nap(3.0)
    acq = functools.reduce(functools.partial(acquire_step, cfg, song), range(12), Acq(False, False, now()))
    if not acq.done:
        return Outcome(False, "playback not confirmed", True)
    reading = poll(functools.partial(confirm, cfg, cand.duration), 5, 1.0)
    start = implied_start(reading) if reading else acq.t_seen
    duration = reading.duration if reading else cand.duration
    started_at = now()
    emit(cfg, song, "playback_started", title=cand.description,
         **({"position": reading.position} if reading else {}))
    natural = pause_deadline(start, duration)
    deadline = natural if cfg.max_play is None else min(natural, started_at + cfg.max_play)
    capped = deadline < natural - 0.001
    resync_at = deadline - RESYNC_LEAD
    start = start if capped or resync_at - now() < 2 else (
        nap_until(resync_at) or refine_start(start, sync(cfg), duration))
    deadline = deadline if capped else pause_deadline(start, duration)
    pressed = pause_video(cfg, deadline)
    if pressed.code != 0:
        return Outcome(False, "pause failed (%d): %s" % (pressed.code, pressed.err.strip()[:120]), False)
    remaining = duration - (now() - start)
    emit(cfg, song, "paused", duration=duration, remaining=round(remaining, 2))
    return Outcome(True, "", False)


def attempt_song(cfg, song, attempt):
    cands, reason = search_candidates(cfg, song)
    if not cands:
        return Outcome(False, reason or "no candidates", True)
    return play_candidate(cfg, song, cands[attempt % len(cands)])


def play_song(cfg, song):
    emit(cfg, song, "song_assigned")
    outcome = functools.reduce(
        lambda prev, i: prev if (prev.ok or not prev.retry) else attempt_song(cfg, song, i),
        range(3), Outcome(False, "not attempted", True))
    return outcome if outcome.ok else (emit(cfg, song, "step_error", reason=outcome.reason) or outcome)


# ----------------------------------------------------------------------------
# Entry point
# ----------------------------------------------------------------------------


def parse_args(argv):
    parser = argparse.ArgumentParser()
    parser.add_argument("--songs", required=True)
    parser.add_argument("--max-songs", type=int, default=None)
    parser.add_argument("--forever", action="store_true")
    parser.add_argument("--start-index", type=int, default=0)
    parser.add_argument("--max-play-seconds", type=float, default=None)
    return parser.parse_args(argv)


def load_config(args):
    return Config(
        pid=os.environ["YUO_CHROME_PID"],
        events=os.environ["YUO_EVENTS"],
        max_play=args.max_play_seconds,
    )


def main(argv):
    args = parse_args(argv)
    cfg = load_config(args)
    songs = tuple(itertools.starmap(Song, enumerate(parse_songs(read_text(args.songs)))))
    if not songs:
        sys.stderr.write("no songs in list\n")
        return 2
    stream = itertools.islice(itertools.cycle(songs), args.start_index % len(songs), None)
    limit = None if args.forever or args.max_songs is None else max(0, args.max_songs)
    limited = stream if limit is None else itertools.islice(stream, limit)
    collections.deque(map(play_song, itertools.repeat(cfg), limited), maxlen=0)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

#!/usr/bin/env python3
"""Play a list of YouTube songs in an already-open Chrome, pausing each 3 s before its end."""
import argparse
import collections
import concurrent.futures
import dataclasses
import functools
import itertools
import json
import os
import re
import subprocess
import sys
import time
from typing import NamedTuple, Optional

# ----------------------------------------------------------------------------
# Immutable data
# ----------------------------------------------------------------------------


@dataclasses.dataclass(frozen=True)
class Config:
    pid: str
    events: str
    max_play: Optional[float]


class Song(NamedTuple):
    index: int
    query: str


class Result(NamedTuple):
    code: int
    out: str
    err: str


class Candidate(NamedTuple):
    path: str
    description: str
    url: str
    duration: int
    score: float


class Reading(NamedTuple):
    position: int
    duration: int
    at: float


class Acq(NamedTuple):
    done: bool
    ad_seen: bool
    t_seen: float


class Outcome(NamedTuple):
    ok: bool
    reason: str
    retry: bool


BAD_WORDS = frozenset((
    "mix", "playlist", "live", "stream", "loop", "looped", "hour", "hours", "reaction",
    "remix", "karaoke", "cover", "slowed", "reverb", "nightcore", "8d", "tutorial",
    "shorts", "short", "instrumental", "sped", "speed",
))
UNIT_SECONDS = (("hour", 3600), ("minute", 60), ("second", 1))
DURATION_RE = re.compile(r"((?:\d+ (?:hours?|minutes?|seconds?)(?:, )?)+)$")
FRAME_RE = re.compile(r'frame="(-?\d+),(-?\d+),(-?\d+),(-?\d+)"')
FALLBACK_CENTRE = (637, 540)
END_MARGIN = 3.0
PRESS_LATENCY = 0.6
RESYNC_LEAD = 15.0
RESULTS_URL = "https://www.youtube.com/results?sp=EgIQAQ%253D%253D&search_query="

# ----------------------------------------------------------------------------
# Functional helpers
# ----------------------------------------------------------------------------

compose = lambda *fns: (lambda x: functools.reduce(lambda acc, f: f(acc), fns, x))
pipe = lambda x, *fns: compose(*fns)(x)


def first_where(pred, items):
    return next(itertools.dropwhile(lambda x: not pred(x), items), None)


def tokens(text):
    return frozenset(re.findall(r"\w+", text.casefold()))


# ----------------------------------------------------------------------------
# Pure parsing / decisions
# ----------------------------------------------------------------------------

keep_line = lambda line: bool(line) and not line.startswith("#")
parse_songs = compose(str.splitlines, functools.partial(map, str.strip),
                      functools.partial(filter, keep_line), tuple)


def quote_byte(b):
    return chr(b) if (48 <= b <= 57 or 65 <= b <= 90 or 97 <= b <= 122) else "%%%02X" % b


def quote_text(text):
    return "".join(map(quote_byte, text.encode("utf-8")))


def results_url(query):
    return RESULTS_URL + quote_text(query)


def parse_json(text):
    try:
        return json.loads(text)
    except ValueError:
        return None


def matches_of(result):
    data = parse_json(result.out) if result.code == 0 else None
    return tuple(m for m in data.get("matches", ()) if isinstance(m, dict)) if isinstance(data, dict) else ()


def phrase_seconds(text):
    parts = re.findall(r"(\d+)\s*(hour|minute|second)", text.casefold())
    units = dict(UNIT_SECONDS)
    return sum(int(n) * units[u] for n, u in parts) if parts else None


def title_duration(title):
    found = DURATION_RE.search(title.strip())
    return phrase_seconds(found.group(1)) if found else None


def find_args(title=None, role=None, identifier=None, limit=8, fmt=None):
    pairs = (("--title", title), ("--role", role), ("--identifier", identifier))
    flags = tuple(itertools.chain.from_iterable((k, v) for k, v in pairs if v))
    tail = ("--format", fmt) if fmt else ()
    return ("find", *flags, "--depth", "40", "--limit", str(limit), *tail)


def role_is(match, name):
    return name in str(match.get("role", "")).lower()


def is_key_button(word, match):
    title = str(match.get("title", ""))
    return title.startswith(word) and ("(k)" in title or "keyboard shortcut" in title)


def derive_box(button_path):
    return button_path[:-2] + ".0.0.0" if button_path.endswith(".1") else button_path


def to_candidate(qtok, bad, indexed):
    i, m = indexed
    title = str(m.get("title") or "")
    desc = str(m.get("description") or "") or title
    url = str(m.get("value") or "")
    dur = title_duration(title)
    words = tokens(desc)
    overlap = len(qtok & words)
    rejected = (
        m.get("identifier") != "video-title" or "/watch" not in url or "/shorts/" in url
        or not m.get("path") or dur is None or not 60 <= dur <= 1200
        or bool(words & bad) or overlap * 2 < len(qtok)
    )
    score = (overlap * 10 + (6 if "official" in words else 0)
             + (2 if words & frozenset(("video", "audio")) else 0) - i * 0.5)
    return None if rejected else Candidate(m["path"], desc, url, dur, score)


def rank_results(query, matches):
    qtok = tokens(query)
    bad = BAD_WORDS - qtok
    cands = filter(None, map(functools.partial(to_candidate, qtok, bad), enumerate(matches)))
    return tuple(sorted(cands, key=lambda c: -c.score))


def split_value(value):
    parts = value.split(" of ")
    pos, dur = (phrase_seconds(parts[0]), phrase_seconds(parts[1])) if len(parts) == 2 else (None, None)
    return (pos, dur) if pos is not None and dur is not None else None


def parse_reading(matches, at):
    usable = filter(lambda m: m.get("enabled") is not False and isinstance(m.get("value"), str), matches)
    pair = next(filter(None, map(lambda m: split_value(m["value"]), usable)), None)
    return Reading(pair[0], pair[1], at) if pair else None


def reading_ok(reading, expected):
    return reading is not None and abs(reading.duration - expected) <= 3 and reading.position <= reading.duration


implied_start = lambda r: r.at - r.position


def consistent(a, b, expected):
    return reading_ok(b, expected) and abs(implied_start(a) - implied_start(b)) <= 2.5


def refine_start(start, reading, expected):
    ok = reading_ok(reading, expected) and abs(implied_start(reading) - start) <= 10
    return implied_start(reading) if ok else start


def pause_deadline(start, duration):
    return start + duration - END_MARGIN - PRESS_LATENCY


def parse_centre(xml_text):
    found = FRAME_RE.search(xml_text)
    x, y, w, h = map(int, found.groups()) if found else (0, 0, 0, 0)
    return (x + w // 2, y + h // 2) if w > 200 and h > 100 and y >= 0 else FALLBACK_CENTRE


def classify(pause, skip, play):
    skips = tuple(m for m in skip if str(m.get("identifier", "")).startswith("skip-button"))
    pauses = tuple(filter(functools.partial(is_key_button, "Pause"), pause))
    plays = tuple(filter(functools.partial(is_key_button, "Play"), play))
    return (("ad", skips[0]) if skips else ("playing", pauses[0]) if pauses
            else ("paused", plays[0]) if plays else ("none", None))


def make_event(t, kind, index, query, extra):
    return {"t": t, "stage": "exploitation", "source": "solution", "kind": kind,
            "song_index": index, "song": query, **extra}


# ----------------------------------------------------------------------------
# Effects: clock, sleep, event file, accessibility calls
# ----------------------------------------------------------------------------


def now():
    return time.time()


def nap(seconds):
    time.sleep(max(0.0, seconds))


def nap_until(moment):
    nap(moment - now())


def run_b4(args):
    prefix = json.loads(os.environ["YUO_B4"])
    try:
        proc = subprocess.run([*prefix, *args], capture_output=True, timeout=90)
        return Result(proc.returncode, proc.stdout.decode("utf-8", "replace"),
                      proc.stderr.decode("utf-8", "replace"))
    except (OSError, subprocess.SubprocessError) as exc:
        return Result(-1, "", str(exc))


def b4(cfg, *args):
    return run_b4((*args, "--pid", cfg.pid))


def emit(cfg, song, kind, **extra):
    line = json.dumps(make_event(now(), kind, song.index, song.query, extra), ensure_ascii=False) + "\n"
    with open(cfg.events, "a", encoding="utf-8") as fh:
        fh.write(line)


def read_text(path):
    with open(path, "r", encoding="utf-8-sig") as fh:
        return fh.read()


def find_matches(cfg, **kw):
    return matches_of(b4(cfg, *find_args(**kw)))


def concurrently(fn, items):
    with concurrent.futures.ThreadPoolExecutor(max_workers=len(items)) as pool:
        return tuple(pool.map(fn, items))


def poll(probe, attempts, interval):
    step = lambda _: probe() or nap(interval)
    bounded = itertools.takewhile(lambda i: i < attempts, itertools.count())
    return next(filter(None, map(step, bounded)), None)


def player_centre(cfg):
    res = b4(cfg, *find_args(identifier="movie_player", limit=1, fmt="xml"))
    return parse_centre(res.out) if res.code == 0 else FALLBACK_CENTRE


def read_slider(cfg):
    before = now()
    matches = find_matches(cfg, title="Seek slider", role="slider", limit=6)
    return parse_reading(matches, (before + now()) / 2)


def sync(cfg):
    cx, cy = player_centre(cfg)
    b4(cfg, "activate")
    b4(cfg, "hover", "--x", str(cx - 40), "--y", str(cy))
    b4(cfg, "hover", "--x", str(cx), "--y", str(cy))
    nap(0.8)
    return read_slider(cfg)


def confirm(cfg, expected):
    first = sync(cfg)
    if not reading_ok(first, expected):
        return None
    second = sync(cfg)
    return second if consistent(first, second, expected) else None


def find_pause(cfg):
    matches = find_matches(cfg, title="Pause", role="button", limit=3)
    return first_where(functools.partial(is_key_button, "Pause"), matches)


def press_target(cfg, target):
    if target is None:
        return Result(-1, "", "pause button not found")
    return b4(cfg, "press", "--path", target["path"], "--expect-description",
              target.get("description") or "Pause")


def pause_video(cfg, deadline):
    nap_until(deadline - 1.5)
    target = find_pause(cfg)
    nap_until(deadline)
    first = press_target(cfg, target)
    return first if first.code == 0 else press_target(cfg, find_pause(cfg))


# ----------------------------------------------------------------------------
# Per-song workflow
# ----------------------------------------------------------------------------


def submit_via_page(cfg, song):
    """Type into YouTube's own search box; return an error text ('' when submitted)."""
    specs = (dict(title="Search", role="combobox", limit=4), dict(title="Search", role="button", limit=8))
    box_ms, btn_ms = concurrently(lambda spec: find_matches(cfg, **spec), specs)
    button = first_where(lambda m: m.get("title") == "Search" and role_is(m, "button"), btn_ms)
    box = first_where(lambda m: m.get("title") == "Search" and role_is(m, "combobox"), box_ms)
    if button is None or box is None:
        return "search box not found"
    typed = b4(cfg, "set-value", "--path", box["path"], "--value", song.query, "--expect-description", "Search")
    if typed.code != 0:
        return "set-value failed: " + typed.err.strip()[:120]
    sent = b4(cfg, "press", "--path", button["path"], "--expect-description", "Search")
    return "" if sent.code == 0 else "search press failed: " + sent.err.strip()[:120]


def submit_via_omnibox(cfg, song):
    """Navigate the current tab to the results URL through the address bar."""
    b4(cfg, "activate")
    bars = find_matches(cfg, title="Address and search bar", role="textfield", limit=4)
    bar = first_where(lambda m: m.get("title") == "Address and search bar", bars)
    if bar is None:
        return "address bar not found"
    url = results_url(song.query)
    desc = str(bar.get("description") or "Address and search bar")
    typed = b4(cfg, "set-value", "--path", bar["path"], "--value", url, "--expect-description", desc)
    if typed.code != 0:
        return "address set-value failed: " + typed.err.strip()[:120]
    sent = b4(cfg, "key", "--key", "return", "--target-path", bar["path"], "--require-value", url)
    return "" if sent.code == 0 else "address submit failed: " + sent.err.strip()[:120]


def search_candidates(cfg, song):
    problem = submit_via_page(cfg, song)
    problem = submit_via_omnibox(cfg, song) if problem else problem
    if problem:
        return (), problem
    nap(2.5)
    found = poll(lambda: rank_results(
        song.query, find_matches(cfg, role="link", identifier="video-title", limit=12)), 5, 1.5)
    return (found or ()), ("" if found else "no suitable result")


def acquire_step(cfg, song, acc, i):
    if acc.done:
        return acc
    pause, skip, play = concurrently(
        lambda t: find_matches(cfg, title=t, role="button", limit=6), ("Pause", "Skip", "Play"))
    state, target = classify(pause, skip, play)
    if state == "playing":
        return Acq(True, acc.ad_seen, now())
    if state == "ad":
        if not acc.ad_seen:
            emit(cfg, song, "ad_seen")
        b4(cfg, "press", "--path", target["path"], "--expect-description", target.get("description") or "Skip")
        nap(1.5)
        return acc._replace(ad_seen=True)
    if state == "paused" and i >= 3:
        b4(cfg, "press", "--path", target["path"], "--expect-description", target.get("description") or "Play")
    nap(1.5 if state == "paused" else 2.0)
    return acc


def play_candidate(cfg, song, cand):
    opened = b4(cfg, "press", "--path", cand.path, "--expect-description", cand.description)
    if opened.code != 0:
        return Outcome(False, "open failed (%d): %s" % (opened.code, opened.err.strip()[:120]), True)
    nap(3.0)
    acq = functools.reduce(functools.partial(acquire_step, cfg, song), range(12), Acq(False, False, now()))
    if not acq.done:
        return Outcome(False, "playback not confirmed", True)
    reading = poll(functools.partial(confirm, cfg, cand.duration), 5, 1.0)
    start = implied_start(reading) if reading else acq.t_seen
    duration = reading.duration if reading else cand.duration
    started_at = now()
    emit(cfg, song, "playback_started", title=cand.description,
         **({"position": reading.position} if reading else {}))
    natural = pause_deadline(start, duration)
    deadline = natural if cfg.max_play is None else min(natural, started_at + cfg.max_play)
    capped = deadline < natural - 0.001
    resync_at = deadline - RESYNC_LEAD
    start = start if capped or resync_at - now() < 2 else (
        nap_until(resync_at) or refine_start(start, sync(cfg), duration))
    deadline = deadline if capped else pause_deadline(start, duration)
    pressed = pause_video(cfg, deadline)
    if pressed.code != 0:
        return Outcome(False, "pause failed (%d): %s" % (pressed.code, pressed.err.strip()[:120]), False)
    remaining = duration - (now() - start)
    emit(cfg, song, "paused", duration=duration, remaining=round(remaining, 2))
    return Outcome(True, "", False)


def attempt_song(cfg, song, attempt):
    cands, reason = search_candidates(cfg, song)
    if not cands:
        return Outcome(False, reason or "no candidates", True)
    return play_candidate(cfg, song, cands[attempt % len(cands)])


def play_song(cfg, song):
    emit(cfg, song, "song_assigned")
    outcome = functools.reduce(
        lambda prev, i: prev if (prev.ok or not prev.retry) else attempt_song(cfg, song, i),
        range(3), Outcome(False, "not attempted", True))
    return outcome if outcome.ok else (emit(cfg, song, "step_error", reason=outcome.reason) or outcome)


# ----------------------------------------------------------------------------
# Entry point
# ----------------------------------------------------------------------------


def parse_args(argv):
    parser = argparse.ArgumentParser()
    parser.add_argument("--songs", required=True)
    parser.add_argument("--max-songs", type=int, default=None)
    parser.add_argument("--forever", action="store_true")
    parser.add_argument("--start-index", type=int, default=0)
    parser.add_argument("--max-play-seconds", type=float, default=None)
    return parser.parse_args(argv)


def load_config(args):
    return Config(
        pid=os.environ["YUO_CHROME_PID"],
        events=os.environ["YUO_EVENTS"],
        max_play=args.max_play_seconds,
    )


def main(argv):
    args = parse_args(argv)
    cfg = load_config(args)
    songs = tuple(itertools.starmap(Song, enumerate(parse_songs(read_text(args.songs)))))
    if not songs:
        sys.stderr.write("no songs in list\n")
        return 2
    stream = itertools.islice(itertools.cycle(songs), args.start_index % len(songs), None)
    limit = None if args.forever or args.max_songs is None else max(0, args.max_songs)
    limited = stream if limit is None else itertools.islice(stream, limit)
    collections.deque(map(play_song, itertools.repeat(cfg), limited), maxlen=0)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

import argparse
import functools
import html
import itertools
import json
import os
import re
import subprocess
import sys
import time
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass
from functools import partial, reduce
from itertools import accumulate, count, cycle, dropwhile, islice, repeat, takewhile
from typing import NamedTuple, Optional


# ---------------------------------------------------------------- data types

class Result(NamedTuple):
    code: int
    out: str
    err: str


class Elem(NamedTuple):
    role: str
    path: str
    title: str
    description: str
    identifier: str
    value: str
    frame: str


class Obs(NamedTuple):
    playing: bool
    ad: bool


class WaitState(NamedTuple):
    obs: Obs
    t: float
    ad_seen: bool
    n: int


class Reading(NamedTuple):
    pos: int
    dur: int
    t: float


class ReadState(NamedTuple):
    reading: Optional[Reading]
    believed: bool
