               "--expect-description", "Search")
    if typed.code != 0:
        return Opened(None, "set-value failed: " + typed.err.strip()[:120])
    submitted = b4("press", "--path", button.path, "--expect-description", "Search")
    if submitted.code != 0:
        return Opened(None, "search submit failed: " + submitted.err.strip()[:120])
    chosen = first(filter(lambda c: c is not None,
                          map(partial(fetch_after, job.query), (2.5, 1.5, 2.0, 2.0, 2.0))))
    if chosen is None:
        return Opened(None, "no suitable video result")
    pressed = b4("press", "--path", chosen.path,
                 "--expect-description", chosen.description or chosen.title)
    if pressed.code != 0:
        return Opened(None, "opening result failed: " + pressed.err.strip()[:120])
    return Opened(chosen, "")


def wait_step(job, prev, _):
    time.sleep(1.0)
    t0 = time.time()
    obs = observe()
    t = (t0 + time.time()) / 2
    if obs.ad and not prev.ad_seen:
        emit("ad_seen", job.idx, job.query)
    return WaitState(obs, t, prev.ad_seen or obs.ad, prev.n + 1)


def try_open(job, _n):
    opened = open_result(job)
    if opened.chosen is None:
        return Attempt(None, opened.reason)
    stream = accumulate(repeat(None, 90), partial(wait_step, job),
                        initial=WaitState(Obs(False, False), 0.0, False, 0))
    ready = next(dropwhile(lambda w: not (w.obs.playing and not w.obs.ad), stream), None)
    if ready is None:
        return Attempt(None, "playback not detected")
    return Attempt(Started(ready.t, duration_from_title(opened.chosen.title)), "")


def read_step(started, prev, _):
    time.sleep(0.0 if prev.tries == 0 else 3.0)
    r = read_once()
    return ReadState(r, believe(r, started.first_seen, started.hint), prev.tries + 1)


def resync_phase(start, dur, target):
    if target - 15.0 - time.time() < 2.0:
        return start
    sleep_until(target - 15.0)
    return resync(start, dur, read_once())


def try_pause(_):
    res = b4("find", "--role", "button", "--title", "Pause", "--depth", "40", "--limit", "5")
    btn = first(filter(is_pause, elems_of(res)))
    if btn is None:
        return None
    pressed = b4("press", "--path", btn.path, "--expect-description", btn.description or btn.title)
    return time.time() if pressed.code == 0 else None


def play_phase(job, started):
    stream = accumulate(repeat(None, 40), partial(read_step, started),
                        initial=ReadState(None, False, 0))
    good = next(filter(lambda s: s.believed, stream), None)
    reading = None if good is None else good.reading
    start, dur = ((reading.t - reading.pos, reading.dur) if reading is not None
                  else (started.first_seen, started.hint))
    if dur is None:
        emit("step_error", job.idx, job.query, reason="video duration unknown")
        return
    extra = {} if reading is None else {"position": round(reading.pos + time.time() - reading.t, 1)}
    emit("playback_started", job.idx, job.query, **extra)
    natural = deadline_for(start, dur)
    cap = None if job.max_play is None else started.first_seen + job.max_play
    target1 = pick_target(natural, cap)
    start2 = start if (cap is not None and cap < natural) else resync_phase(start, dur, target1)
    sleep_until(pick_target(deadline_for(start2, dur), cap))
    done = next(filter(lambda t: t is not None, map(try_pause, range(3))), None)
    if done is None:
        emit("step_error", job.idx, job.query, reason="pause failed")
        return
    emit("paused", job.idx, job.query, duration=dur, remaining=round(start2 + dur - done, 2))


def play_song(job):
    attempts = accumulate(takewhile(lambda n: n < 3, count()),
                          lambda prev, n: prev if prev.started is not None else try_open(job, n),
                          initial=Attempt(None, "not tried"))
    final = reduce(lambda _, x: x, attempts)
    if final.started is None:
        emit("step_error", job.idx, job.query,
             reason="could not find or play song: " + final.reason)
        return
    play_phase(job, final.started)


def run_song(job):
    emit("song_assigned", job.idx, job.query)
    try:
        play_song(job)
    except Exception as exc:
        emit("step_error", job.idx, job.query, reason="unexpected error: " + str(exc)[:200])


def main(argv):
    args = parse_args(argv)
    songs = parse_songs(read_text(args.songs))
    if not songs:
        return 1
    limit = None if args.forever else args.max_songs
    positions = islice(cycle(range(len(songs))), args.start_index % len(songs), None)
    jobs = map(lambda i: Job(i, songs[i], args.max_play_seconds), islice(positions, limit))
    tuple(map(run_song, jobs))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

import argparse
import functools
import html
import itertools
import json
import os
import re
import subprocess
import sys
import time
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass
from functools import partial, reduce
from itertools import accumulate, count, cycle, dropwhile, islice, repeat, takewhile
from typing import NamedTuple, Optional


# ---------------------------------------------------------------- data types

class Result(NamedTuple):
    code: int
    out: str
    err: str


class Elem(NamedTuple):
    role: str
    path: str
    title: str
    description: str
    identifier: str
    value: str
    frame: str


class Obs(NamedTuple):
    playing: bool
    ad: bool


class WaitState(NamedTuple):
    obs: Obs
    t: float
    ad_seen: bool
    n: int


class Reading(NamedTuple):
    pos: int
    dur: int
    t: float


class ReadState(NamedTuple):
    reading: Optional[Reading]
    believed: bool
    tries: int


class Started(NamedTuple):
    first_seen: float
    hint: Optional[int]


class Attempt(NamedTuple):
    started: Optional[Started]
    reason: str


class Opened(NamedTuple):
    chosen: Optional[Elem]
    reason: str


@dataclass(frozen=True)
class Job:
    idx: int
    query: str
    max_play: Optional[float]


# ---------------------------------------------------------------- constants

AD_TITLES = frozenset(("Sponsored", "My Ad Center", "Skip", "Skip Ad", "Skip Ads"))
BANNED_WORDS = frozenset((
    "mix", "playlist", "live", "loop", "looped", "hour", "hours", "shorts",
    "reaction", "karaoke", "slowed", "reverb", "8d", "nightcore", "sped",
))
DURATION_UNITS = (
    (re.compile(r"(\d+)\s+hours?\b", re.I), 3600),
    (re.compile(r"(\d+)\s+minutes?\b", re.I), 60),
    (re.compile(r"(\d+)\s+seconds?\b", re.I), 1),
)
TAG_RE = re.compile(r"<(AX\w+)\s([^>]*?)/?>")
ATTR_RE = re.compile(r'(\w+)="([^"]*)"')
CLOCK = r"(?:(\d+) Hours? )?(\d+) Minutes? (\d+) Seconds?"
SLIDER_RE = re.compile(CLOCK + " of " + CLOCK, re.I)
PAUSE_LATENCY = 0.6
END_MARGIN = 3.0
OMNIBOX_TITLE = "Address and search bar"
OMNIBOX_DESCRIPTIONS = ("Address and search bar", "Ask Google or type a URL")


# ---------------------------------------------------------------- helpers (pure)

def compose(*fs):
    return lambda x: reduce(lambda acc, f: f(acc), fs, x)


def pipe(x, *fs):
    return compose(*fs)(x)


first = lambda items, default=None: next(iter(items), default)
keep_line = lambda line: bool(line) and not line.startswith("#")
parse_songs = compose(str.splitlines, partial(map, str.strip), partial(filter, keep_line), tuple)


def safe_json(text):
    try:
        return json.loads(text)
    except ValueError:
        return None


def elem_from(role, d):
    g = lambda k: str(d.get(k) or "")
    return Elem(role, g("path"), g("title"), g("description"),
                g("identifier") or g("id"), g("value"), g("frame"))


def parse_json_matches(text):
    data = safe_json(text)
    items = data.get("matches", ()) if isinstance(data, dict) else ()
    return tuple(map(lambda m: elem_from(str(m.get("role", "")), m),
                     filter(lambda m: isinstance(m, dict), items)))


def parse_xml(text):
    attrs = lambda raw: dict(map(lambda a: (a[0], html.unescape(a[1])), ATTR_RE.findall(raw)))
    return tuple(map(lambda m: elem_from(m.group(1), attrs(m.group(2))), TAG_RE.finditer(text)))


def elems_of(res, xml=False):
    if res.code != 0:
        return ()
    return parse_xml(res.out) if xml else parse_json_matches(res.out)


def duration_from_title(title):
    parts = tuple(itertools.chain.from_iterable(map(
        lambda unit: tuple(map(lambda n: int(n) * unit[1], unit[0].findall(title)[-1:])),
        DURATION_UNITS)))
    return sum(parts) if parts else None


def words(text):
    return frozenset(re.findall(r"[\w']+", text.lower()))


def acceptable(query, e):
    length = duration_from_title(e.title)
    banned = (words(e.title) & BANNED_WORDS) - words(query)
    return (e.identifier == "video-title" and "watch?v=" in e.value
            and not banned and length is not None and 60 <= length <= 1500)


def score(query, e):
    return 2 * len(words(query) & words(e.title)) + (1 if "official" in e.title.lower() else 0)


def choose_result(query, elems):
    return max(filter(partial(acceptable, query), elems), key=partial(score, query), default=None)


def is_pause(e):
    return e.title.startswith("Pause") and "button" in e.role.lower()


def is_ad_marker(e):
    return e.title in AD_TITLES or e.description in AD_TITLES


def is_search_box(e):
    role = e.role.lower()
    return e.title == "Search" and any(map(lambda k: k in role, ("combobox", "textfield", "edit")))


def is_search_button(e):
    return e.title == "Search" and "button" in e.role.lower()


def controls_ready(c):
    return c[0] is not None and c[1] is not None


def percent_encode(text):
    safe = frozenset(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.~")
    return "".join(map(lambda b: chr(b) if b in safe else "%{:02X}".format(b),
                       text.encode("utf-8")))


def search_url(query):
    return "https://www.youtube.com/results?search_query=" + percent_encode(query)


def frame_center(frame):
    nums = tuple(map(int, re.findall(r"-?\d+", frame)))
    return (nums[0] + nums[2] // 2, nums[1] + nums[3] // 2) if len(nums) == 4 else (637, 540)


def clock_seconds(groups):
    h, m, s = map(lambda g: int(g or 0), groups)
    return h * 3600 + m * 60 + s


def parse_slider(text):
    m = SLIDER_RE.search(text)
    return None if m is None else (clock_seconds(m.groups()[:3]), clock_seconds(m.groups()[3:]))


def believe(reading, first_seen, hint):
    return (reading is not None
            and reading.dur >= 60
            and (hint is None or abs(reading.dur - hint) <= 3)
            and first_seen - 10 <= reading.t - reading.pos <= first_seen + 60)


def deadline_for(start, dur):
    return start + dur - END_MARGIN - PAUSE_LATENCY


def pick_target(natural, cap):
    return natural if cap is None else min(natural, cap)


def resync(start, dur, r2):
    ok = (r2 is not None and abs(r2.dur - dur) <= 1
          and abs((r2.t - r2.pos) - start) <= 10)
    return r2.t - r2.pos if ok else start


def build_record(kind, idx, song, extra, now):
    return {"t": now, "stage": "exploitation", "source": "solution", "kind": kind,
            "song_index": idx, "song": song, **extra}


def parse_args(argv):
    parser = argparse.ArgumentParser()
    parser.add_argument("--songs", required=True)
    parser.add_argument("--max-songs", type=int, default=None)
    parser.add_argument("--forever", action="store_true")
    parser.add_argument("--start-index", type=int, default=0)
    parser.add_argument("--max-play-seconds", type=float, default=None)
    return parser.parse_args(argv)


# ---------------------------------------------------------------- effects

def b4(*parts):
    prefix = json.loads(os.environ["YUO_B4"])
    pid = os.environ["YUO_CHROME_PID"]
    args = (*parts, "--pid", pid)
    proc = subprocess.run([*prefix, *args], capture_output=True)
    return Result(proc.returncode,
                  proc.stdout.decode("utf-8", errors="replace"),
                  proc.stderr.decode("utf-8", errors="replace"))


def b4_many(arglists):
    with ThreadPoolExecutor(max_workers=4) as pool:
        return tuple(pool.map(lambda a: b4(*a), arglists))


def emit(kind, idx, song, **extra):
    record = build_record(kind, idx, song, extra, time.time())
    with open(os.environ["YUO_EVENTS"], "a", encoding="utf-8") as fh:
        fh.write(json.dumps(record, ensure_ascii=False) + "\n")


def sleep_until(t):
    time.sleep(max(0.0, t - time.time()))


def read_text(path):
    with open(path, encoding="utf-8-sig") as fh:
        return fh.read()


def locate_player():
    res = b4("find", "--identifier", "movie_player", "--depth", "40",
             "--limit", "1", "--format", "xml")
    return first(elems_of(res, xml=True))


def observe():
    player = locate_player()
    if player is None:
        return Obs(False, False)
    ad_calls = tuple(map(
        lambda t: ("find", "--under", player.path, "--depth", "5", "--limit", "10", "--title", t),
        ("Sponsored", "My Ad Center", "Skip")))
    pause_call = ("find", "--role", "button", "--title", "Pause", "--depth", "40", "--limit", "5")
    results = b4_many((*ad_calls, pause_call))
    ads = itertools.chain.from_iterable(map(elems_of, results[:3]))
    return Obs(any(map(is_pause, elems_of(results[3]))), any(map(is_ad_marker, ads)))


def read_once():
    player = locate_player()
    if player is None:
        return None
    cx, cy = frame_center(player.frame)
    b4("activate")
    b4("hover", "--x", str(cx - 40), "--y", str(cy))
    b4("hover", "--x", str(cx), "--y", str(cy))
    time.sleep(0.8)
    res = b4("find", "--title", "Seek slider", "--role", "slider",
             "--under", player.path, "--depth", "8", "--limit", "1")
    t = time.time()
    slider = first(elems_of(res))
    parsed = None if slider is None else parse_slider(slider.value)
    return None if parsed is None else Reading(parsed[0], parsed[1], t)


def fetch_after(query, delay):
    time.sleep(delay)
    res = b4("find", "--role", "link", "--identifier", "video-title",
             "--depth", "40", "--limit", "25")
    return choose_result(query, elems_of(res))


def probe_controls(delay):
    time.sleep(delay)
    found = elems_of(b4("find", "--title", "Search", "--depth", "40", "--limit", "40"))
    return (first(filter(is_search_box, found)),
            first(filter(is_search_button, found)))


def submit_via_page(job, box, button):
    typed = b4("set-value", "--path", box.path, "--value", job.query,
               "--expect-description", "Search")
    if typed.code != 0:
        return "set-value failed: " + typed.err.strip()[:120]
    submitted = b4("press", "--path", button.path, "--expect-description", "Search")
    return "" if submitted.code == 0 else "search submit failed: " + submitted.err.strip()[:120]


def submit_via_omnibox(job):
    bar = first(filter(lambda e: e.title == OMNIBOX_TITLE,
                       elems_of(b4("find", "--title", OMNIBOX_TITLE, "--depth", "40", "--limit", "5"))))
    if bar is None:
        return "search controls not found"
    url = search_url(job.query)
    b4("activate")
    typed = first(filter(lambda r: r.code == 0,
                         map(lambda d: b4("set-value", "--path", bar.path, "--value", url,
                                          "--expect-description", d),
                             OMNIBOX_DESCRIPTIONS)))
    if typed is None:
        return "omnibox set-value failed"
    sent = b4("key", "--key", "return", "--target-path", bar.path, "--require-value", url)
    return "" if sent.code == 0 else "omnibox submit failed: " + sent.err.strip()[:120]


def open_result(job):
    b4("activate")
    box, button = next(
        filter(controls_ready,
               map(probe_controls, itertools.chain((0.0,), repeat(2.0, 4)))),
        (None, None))
    reason = (submit_via_omnibox(job) if (box is None or button is None)
              else submit_via_page(job, box, button))
    if reason:
        return Opened(None, reason)
    chosen = first(filter(lambda c: c is not None,
                          map(partial(fetch_after, job.query), (2.5, 1.5, 2.0, 2.0, 2.0, 3.0))))
    if chosen is None:
        return Opened(None, "no suitable video result")
    pressed = b4("press", "--path", chosen.path,
                 "--expect-description", chosen.description or chosen.title)
    if pressed.code != 0:
        return Opened(None, "opening result failed: " + pressed.err.strip()[:120])
    return Opened(chosen, "")


def wait_step(job, prev, _):
    time.sleep(1.0)
    t0 = time.time()
    obs = observe()
    t = (t0 + time.time()) / 2
    if obs.ad and not prev.ad_seen:
        emit("ad_seen", job.idx, job.query)
    return WaitState(obs, t, prev.ad_seen or obs.ad, prev.n + 1)


def try_open(job, _n):
    opened = open_result(job)
    if opened.chosen is None:
        return Attempt(None, opened.reason)
    stream = accumulate(repeat(None, 90), partial(wait_step, job),
                        initial=WaitState(Obs(False, False), 0.0, False, 0))
    ready = next(dropwhile(lambda w: not (w.obs.playing and not w.obs.ad), stream), None)
    if ready is None:
        return Attempt(None, "playback not detected")
    return Attempt(Started(ready.t, duration_from_title(opened.chosen.title)), "")


def read_step(started, prev, _):
    time.sleep(0.0 if prev.tries == 0 else 3.0)
    r = read_once()
    return ReadState(r, believe(r, started.first_seen, started.hint), prev.tries + 1)


def resync_phase(start, dur, target):
    if target - 15.0 - time.time() < 2.0:
        return start
    sleep_until(target - 15.0)
    return resync(start, dur, read_once())


def try_pause(_):
    res = b4("find", "--role", "button", "--title", "Pause", "--depth", "40", "--limit", "5")
    btn = first(filter(is_pause, elems_of(res)))
    if btn is None:
        return None
    pressed = b4("press", "--path", btn.path, "--expect-description", btn.description or btn.title)
    return time.time() if pressed.code == 0 else None


def play_phase(job, started):
    stream = accumulate(repeat(None, 12), partial(read_step, started),
                        initial=ReadState(None, False, 0))
    good = next(filter(lambda s: s.believed, stream), None)
    reading = None if good is None else good.reading
    start, dur = ((reading.t - reading.pos, reading.dur) if reading is not None
                  else (started.first_seen, started.hint))
    if dur is None:
        emit("step_error", job.idx, job.query, reason="video duration unknown")
        return
    extra = {} if reading is None else {"position": round(reading.pos + time.time() - reading.t, 1)}
    emit("playback_started", job.idx, job.query, **extra)
    natural = deadline_for(start, dur)
    cap = None if job.max_play is None else started.first_seen + job.max_play
    target1 = pick_target(natural, cap)
    start2 = start if (cap is not None and cap < natural) else resync_phase(start, dur, target1)
    sleep_until(pick_target(deadline_for(start2, dur), cap))
    done = next(filter(lambda t: t is not None, map(try_pause, range(3))), None)
    if done is None:
        emit("step_error", job.idx, job.query, reason="pause failed")
        return
    emit("paused", job.idx, job.query, duration=dur, remaining=round(start2 + dur - done, 2))


def play_song(job):
    attempts = accumulate(takewhile(lambda n: n < 3, count()),
                          lambda prev, n: prev if prev.started is not None else try_open(job, n),
                          initial=Attempt(None, "not tried"))
    final = reduce(lambda _, x: x, attempts)
    if final.started is None:
        emit("step_error", job.idx, job.query,
             reason="could not find or play song: " + final.reason)
        return
    play_phase(job, final.started)


def run_song(job):
    emit("song_assigned", job.idx, job.query)
    try:
        play_song(job)
    except Exception as exc:
        emit("step_error", job.idx, job.query, reason="unexpected error: " + str(exc)[:200])


def main(argv):
    args = parse_args(argv)
    songs = parse_songs(read_text(args.songs))
    if not songs:
        return 1
    limit = None if args.forever else args.max_songs
    positions = islice(cycle(range(len(songs))), args.start_index % len(songs), None)
    jobs = map(lambda i: Job(i, songs[i], args.max_play_seconds), islice(positions, limit))
    tuple(map(run_song, jobs))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

#!/usr/bin/env python3
"""Play a list of YouTube songs in an already-open Chrome, driven only through
the accessibility command-line proxy named by the YUO_B4 environment variable.

Style: pure functions decide, a small set of fx_* functions perform effects,
all data is immutable and iteration is lazy.
"""

import concurrent.futures
import dataclasses
import functools
import itertools
import json
import os
import re
import subprocess
import sys
import time
import types
from functools import partial
from typing import Any, NamedTuple, Optional

ATTEMPT_BUDGET = 120.0
MAX_ATTEMPTS = 3
MAX_READINGS = 40
PAUSE_MARGIN = 3.0
CALL_LATENCY = 0.6
RESYNC_LEAD = 15.0
AD_TITLES = frozenset({"Sponsored", "My Ad Center", "Skip", "Skip Ad", "Skip Ads"})
BAD_WORDS = frozenset({
    "mix", "playlist", "live", "loop", "looped", "loops", "shorts", "short", "hour", "hours",
    "cover", "karaoke", "reaction", "remix", "slowed", "reverb", "sped", "nightcore",
    "tutorial", "lesson", "stream", "radio",
})
UNIT_SECONDS = types.MappingProxyType({"hour": 3600, "minute": 60, "second": 1})
DURATION_TAIL = re.compile(r"((?:\d+\s+(?:hour|minute|second)s?,?\s*)+)$")
CLOCK_RE = re.compile(r"(?:(\d+)\s*Hours?\s*)?(?:(\d+)\s*Minutes?\s*)?(\d+)\s*Seconds?", re.I)
PLAY_TITLE_RE = re.compile(r"Play\s*(\(k\)|keyboard)")


# ----------------------------------------------------------------- data types

class B4Result(NamedTuple):
    code: int
    data: Any
    err: str


class Stage(NamedTuple):
    ok: bool
    value: Any
    reason: str


class Config(NamedTuple):
    songs_path: str
    max_songs: Optional[int]
    start: int
    max_play: Optional[float]


class Reading(NamedTuple):
    t: float
    pos: int
    dur: int


class Obs(NamedTuple):
    t: float
    player: Optional[dict]
    markers: tuple
    skip: Optional[dict]
    pause: Optional[dict]
    play: Optional[dict]


class Tally(NamedTuple):
    streak: int
    done: bool


@dataclasses.dataclass(frozen=True)
class Ctx:
    idx: int
    query: str
    deadline: float
    max_play: Optional[float]


@dataclasses.dataclass(frozen=True)
class Belief:
    start: float
    dur: float
    pos: float
    seen: float


@dataclasses.dataclass(frozen=True)
class Flow:
    ctx: Ctx
    expected: Optional[int] = None
    belief: Optional[Belief] = None


@dataclasses.dataclass(frozen=True)
class PlayState:
    last_ad: float = float("-inf")
    first_clear: Optional[float] = None
    in_ad: bool = False
    readings: int = 0
    belief: Optional[Belief] = None
    timed_out: bool = False


@dataclasses.dataclass(frozen=True)
class Run:
    streak: int
    song_fails: int
    abort: bool
    stop: bool


# --------------------------------------------------------------- pure helpers

def compose(*fns):
    return functools.reduce(lambda f, g: lambda x: g(f(x)), fns, lambda x: x)


def pipe(value, *fns):
    return compose(*fns)(value)


def first(seq):
    return next(iter(seq), None)


def succeed(value):
    return Stage(True, value, "")


def fail(reason):
    return Stage(False, None, reason)


def bind(stage, fn):
    return fn(stage.value) if stage.ok else stage


def keep_line(line):
    return bool(line) and not line.startswith("#")


def parse_songs(text):
    return pipe(text, str.splitlines, partial(map, str.strip), partial(filter, keep_line), tuple)


def value_of(tokens, flag):
    return next((tokens[i + 1] for i, tok in enumerate(tokens[:-1]) if tok == flag), None)


def normalize_tokens(argv):
    return tuple(itertools.chain.from_iterable(
        tok.split("=", 1) if tok.startswith("--") else (tok,) for tok in argv))


def parse_config(argv):
    tokens = normalize_tokens(argv)
    path = value_of(tokens, "--songs")
    max_songs = value_of(tokens, "--max-songs")
    max_play = value_of(tokens, "--max-play-seconds")
    return Config(
        path,
        None if max_songs is None else int(max_songs),
        int(value_of(tokens, "--start-index") or 0),
        None if max_play is None else float(max_play),
    )


def song_stream(songs, start, limit):
    indexed = tuple(zip(itertools.count(), songs))
    begin = start % len(indexed)
    return itertools.islice(itertools.cycle(indexed), begin, None if limit is None else begin + limit)


def backoff_delay(streak):
    return min(60.0, 5.0 * 2 ** max(0, streak - 1))


def make_event(now, kind, idx, query, extra):
    return {"t": now, "stage": "exploitation", "source": "solution", "kind": kind,
            "song_index": idx, "song": query, **extra}


def parse_json(text):
    try:
        return json.loads(text)
    except ValueError:
        return None


def matches_of(res):
    items = res.data.get("matches") if res.code == 0 and isinstance(res.data, dict) else None
    return tuple(filter(lambda m: isinstance(m, dict), items or ()))


def find_args(*, title=None, role=None, identifier=None, under=None, depth=None, limit=None):
    pairs = (("--title", title), ("--role", role), ("--identifier", identifier),
             ("--under", under), ("--depth", depth), ("--limit", limit))
    return ("find", *itertools.chain.from_iterable((k, str(v)) for k, v in pairs if v is not None))


def text_of(el, key):
    return str(el.get(key) or "").strip()


def exact_title(el, title):
    return text_of(el, "title") == title


def is_pause_el(el):
    return text_of(el, "title").startswith("Pause")


def parse_frame(el):
    raw = el.get("frame")
    nums = tuple(map(float, re.findall(r"-?\d+(?:\.\d+)?", json.dumps(raw)))) if raw is not None else ()
    return nums[:4] if len(nums) >= 4 else None


def hover_points(player):
    frame = parse_frame(player) if player else None
    cx, cy = (frame[0] + frame[2] / 2, frame[1] + frame[3] / 2) if frame else (637.0, 540.0)
    return ((int(cx - 40), int(cy)), (int(cx), int(cy)))


def words(text):
    return frozenset(re.findall(r"\w+", text.lower()))


def title_duration(title):
    m = DURATION_TAIL.search(title.strip())
    return None if m is None else sum(
        int(n) * UNIT_SECONDS[u] for n, u in re.findall(r"(\d+)\s+(hour|minute|second)", m.group(1)))


def clean_title(el):
    return text_of(el, "description") or DURATION_TAIL.sub("", text_of(el, "title")).strip()


def is_candidate(query, el):
    url = text_of(el, "value")
    name_words = words(clean_title(el))
    query_words = words(query)
    duration = title_duration(text_of(el, "title"))
    overlap = len(query_words & name_words) / max(1, len(query_words))
    return ("/watch?v=" in url and "/shorts/" not in url
            and duration is not None and 60 <= duration <= 1800
            and not ((name_words & BAD_WORDS) - query_words)
            and overlap >= 0.5)


def choose_candidates(query, els):
    rest = tuple(itertools.dropwhile(lambda e: not is_candidate(query, e), els))
    return tuple(itertools.islice(filter(partial(is_candidate, query), rest), 5))


def longest_word(query):
    return max(re.findall(r"\w+", query) or [query], key=len)


def parse_clock(text):
    m = CLOCK_RE.search(text)
    return None if m is None else int(m.group(1) or 0) * 3600 + int(m.group(2) or 0) * 60 + int(m.group(3))


def parse_slider(value):
    parts = re.split(r"\s+of\s+", str(value or ""), maxsplit=1)
    pair = tuple(map(parse_clock, parts)) if len(parts) == 2 else ()
    return pair if len(pair) == 2 and None not in pair else None


def make_obs(t, player, results):
    sponsored, ad_center, skip, pause, play = map(matches_of, results)
    markers = tuple(filter(lambda e: text_of(e, "title") in AD_TITLES, (*sponsored, *ad_center, *skip)))
    skips = tuple(filter(lambda e: text_of(e, "identifier").startswith("skip-button")
                         and e.get("enabled") is not False, skip))
    return Obs(
        t, player, markers, first(skips),
        first(filter(is_pause_el, pause)),
        first(filter(lambda e: PLAY_TITLE_RE.match(text_of(e, "title")), play)),
    )


def decide(obs):
    if obs.player is None:
        return "wait"
    if obs.skip is not None:
        return "skip"
    if obs.markers:
        return "wait"
    if obs.pause is not None:
        return "read"
    if obs.play is not None:
        return "play"
    return "wait"


def observe_update(st, obs):
    ad = bool(obs.markers)
    clear = obs.pause is not None and not ad
    return dataclasses.replace(
        st,
        last_ad=obs.t if ad else st.last_ad,
        first_clear=None if ad else (st.first_clear if st.first_clear is not None
                                     else (obs.t if clear else None)),
        in_ad=ad,
    )


def is_song_length(expected, reading):
    return reading.dur >= 60 and (expected is None or abs(reading.dur - expected) <= 5)


def implied_start(reading):
    return reading.t - reading.pos - 0.5


def believable(st, expected, reading):
    start = implied_start(reading)
    return (is_song_length(expected, reading)
            and start >= st.last_ad - 3.0
            and start <= reading.t
            and (st.first_clear is None or start <= st.first_clear + 60.0))


def target_time(belief, max_play):
    natural = belief.start + belief.dur - PAUSE_MARGIN - CALL_LATENCY
    return natural if max_play is None else min(natural, belief.seen + max_play)


def resync_belief(belief, reading):
    if reading is None:
        return belief
    start = implied_start(reading)
    agrees = abs(reading.dur - belief.dur) <= 3 and abs(start - belief.start) <= 10
    return dataclasses.replace(belief, start=start) if agrees else belief


# -------------------------------------------------------------------- effects

def fx_mono():
    return time.monotonic()


def fx_sleep(seconds):
    time.sleep(max(0.0, seconds))


def fx_sleep_until(moment):
    fx_sleep(moment - time.monotonic())


def fx_emit(kind, idx, query, **extra):
    event = make_event(time.time(), kind, idx, query, extra)
    with open(os.environ["YUO_EVENTS"], "a", encoding="utf-8") as handle:
        handle.write(json.dumps(event, ensure_ascii=False) + "\n")


def fx_b4(raw_args):
    prefix = json.loads(os.environ["YUO_B4"])
    args = (*raw_args, "--pid", os.environ["YUO_CHROME_PID"])
    try:
        proc = subprocess.run([*prefix, *args], capture_output=True, timeout=90)
    except subprocess.TimeoutExpired:
        return B4Result(-1, None, "timeout")
    except OSError as exc:
        return B4Result(-2, None, repr(exc))
    out = proc.stdout.decode("utf-8", errors="replace")
    err = proc.stderr.decode("utf-8", errors="replace")
    return B4Result(proc.returncode, parse_json(out), err)


def fx_parallel(thunks):
    with concurrent.futures.ThreadPoolExecutor(max_workers=max(1, len(thunks))) as pool:
        return tuple(pool.map(lambda thunk: thunk(), thunks))


def fx_press(path, expect):
    return fx_b4(("press", "--path", path, "--expect-description", expect)).code == 0


def fx_read_songs(path):
    with open(path, encoding="utf-8-sig") as handle:
        return parse_songs(handle.read())


def fx_find_player():
    return first(matches_of(fx_b4(find_args(identifier="movie_player", depth=40, limit=1))))


def fx_observe():
    player = fx_find_player()
    if player is None:
        return Obs(fx_mono(), None, (), None, None, None)
    path = player["path"]
    thunks = (
        partial(fx_b4, find_args(title="Sponsored", under=path, depth=5, limit=5)),
        partial(fx_b4, find_args(title="My Ad Center", under=path, depth=5, limit=5)),
        partial(fx_b4, find_args(title="Skip", under=path, depth=5, limit=8)),
        partial(fx_b4, find_args(title="Pause", under=path, depth=8, limit=1)),
        partial(fx_b4, find_args(title="Play", under=path, depth=8, limit=6)),
    )
    results = fx_parallel(thunks)
    return make_obs(fx_mono(), player, results)


def fx_read_position(player):
    fx_b4(("activate",))
    tuple(map(lambda p: fx_b4(("hover", "--x", str(p[0]), "--y", str(p[1]))), hover_points(player)))
    fx_sleep(0.8)
    res = fx_b4(find_args(title="Seek slider", role="AXSlider", under=player["path"], depth=6, limit=1))
    stamp = fx_mono()
    el = first(matches_of(res))
    parsed = parse_slider(el.get("value")) if el else None
    return Reading(stamp, parsed[0], parsed[1]) if parsed else None


def fx_find_pause():
    player = fx_find_player()
    if player is None:
        return None
    res = fx_b4(find_args(title="Pause", under=player["path"], depth=8, limit=1))
    return first(filter(is_pause_el, matches_of(res)))


def fx_pause_now(path):
    if path is not None and fx_press(path, "Pause (k)"):
        return True
    el = fx_find_pause()
    return el is not None and fx_press(el["path"], text_of(el, "description") or text_of(el, "title") or "Pause")


# ----------------------------------------------------------- confirm-playing

def fx_act_skip(flow, st, obs):
    fx_press(obs.skip["path"], "Skip")
    fx_sleep(1.0)
    return st


def fx_act_wait(flow, st, obs):
    fx_sleep(1.0)
    return st


def fx_act_play(flow, st, obs):
    fx_press(obs.play["path"], text_of(obs.play, "description") or "Play (k)")
    fx_sleep(1.5)
    return st


def fx_act_read(flow, st, obs):
    ctx = flow.ctx
    reading = fx_read_position(obs.player)
    if reading is None:
        fx_sleep(2.0)
        return dataclasses.replace(st, readings=st.readings + 1)
    if believable(st, flow.expected, reading):
        fx_emit("playback_started", ctx.idx, ctx.query, position=reading.pos)
        belief = Belief(implied_start(reading), float(reading.dur), float(reading.pos), reading.t)
        return dataclasses.replace(st, belief=belief)
    fx_sleep(4.0)
    return dataclasses.replace(
        st,
        readings=st.readings + 1,
        last_ad=st.last_ad if is_song_length(flow.expected, reading) else max(st.last_ad, reading.t),
    )


ACTIONS = types.MappingProxyType({
    "skip": fx_act_skip,
    "wait": fx_act_wait,
    "play": fx_act_play,
    "read": fx_act_read,
})


def fx_confirm_step(flow, st, _):
    ctx = flow.ctx
    if fx_mono() > ctx.deadline or st.readings >= MAX_READINGS:
        return dataclasses.replace(st, timed_out=True)
    obs = fx_observe()
    nxt = observe_update(st, obs)
    if obs.markers and not st.in_ad:
        fx_emit("ad_seen", ctx.idx, ctx.query, skippable=obs.skip is not None)
    return ACTIONS[decide(obs)](flow, nxt, obs)


# --------------------------------------------------------------------- stages

def stage_submit(flow):
    ctx = flow.ctx
    box = first(filter(lambda e: exact_title(e, "Search"),
                       matches_of(fx_b4(find_args(role="combobox", title="Search", depth=40, limit=4)))))
    if box is None:
        return fail("search box not found")
    typed = fx_b4(("set-value", "--path", box["path"], "--value", ctx.query, "--expect-description", "Search"))
    if typed.code != 0:
        return fail(f"set-value failed (exit {typed.code})")
    button = first(filter(lambda e: exact_title(e, "Search"),
                          matches_of(fx_b4(find_args(role="button", title="Search", depth=40, limit=8)))))
    if button is None:
        return fail("search button not found")
    if not fx_press(button["path"], "Search"):
        return fail("search button press failed")
    fx_sleep(2.5)
    return succeed(flow)


def fx_results_once(ctx):
    finders = (
        partial(fx_b4, find_args(role="link", identifier="video-title", depth=40, limit=20)),
        partial(fx_b4, find_args(role="link", title=longest_word(ctx.query), depth=40, limit=20)),
    )
    cands = next(filter(None, map(lambda f: choose_candidates(ctx.query, matches_of(f())), finders)), ())
    if cands:
        return succeed(cands)
    if fx_mono() > ctx.deadline:
        return fail("no suitable search result")
    fx_sleep(1.5)
    return Stage(False, None, "")


def fx_poll_results(ctx):
    return next(filter(lambda s: s.ok or s.reason, map(lambda _: fx_results_once(ctx), itertools.repeat(None))))


def fx_open_first(flow, cands):
    attempts = map(lambda c: (c, fx_b4(("press", "--path", c["path"], "--expect-description", clean_title(c)))), cands)
    chosen = next(filter(lambda pair: pair[1].code == 0, attempts), None)
    if chosen is None:
        return fail("every result press was refused")
    fx_sleep(3.0)
    return succeed(dataclasses.replace(flow, expected=title_duration(text_of(chosen[0], "title"))))


def stage_open(flow):
    return bind(fx_poll_results(flow.ctx), partial(fx_open_first, flow))


def stage_confirm(flow):
    stream = itertools.accumulate(itertools.repeat(None), partial(fx_confirm_step, flow), initial=PlayState())
    final = next(filter(lambda s: s.belief is not None or s.timed_out, stream))
    if final.belief is None:
        return fail("song did not start playing in time")
    return succeed(dataclasses.replace(flow, belief=final.belief))


def fx_resync(belief, target):
    obs = fx_observe()
    if obs.player is None:
        return belief, None
    if obs.skip is not None:
        fx_press(obs.skip["path"], "Skip")
    reading = fx_read_position(obs.player) if target - fx_mono() > 5.0 else None
    found = fx_b4(find_args(title="Pause", under=obs.player["path"], depth=8, limit=1))
    pause_el = first(filter(is_pause_el, matches_of(found)))
    return resync_belief(belief, reading), (pause_el["path"] if pause_el else None)


def stage_finish(flow):
    ctx = flow.ctx
    belief = flow.belief
    first_target = target_time(belief, ctx.max_play)
    fx_sleep_until(first_target - RESYNC_LEAD)
    synced, path = fx_resync(belief, first_target)
    fx_sleep_until(target_time(synced, ctx.max_play))
    if not fx_pause_now(path):
        return fail("pause control not pressable")
    remaining = synced.start + synced.dur - fx_mono()
    fx_emit("paused", ctx.idx, ctx.query, duration=int(round(synced.dur)), remaining=round(remaining, 2))
    return succeed(flow)


def fx_attempt(ctx):
    stages = (stage_submit, stage_open, stage_confirm, stage_finish)
    return functools.reduce(bind, stages, succeed(Flow(ctx)))


def fx_attempt_safe(ctx):
    try:
        return fx_attempt(ctx)
    except Exception as exc:
        return fail(f"exception: {exc!r}")


# ---------------------------------------------------------------- song driver

def fx_try_attempt(cfg, idx, query, tally, number):
    if tally.done:
        return tally
    ctx = Ctx(idx, query, fx_mono() + ATTEMPT_BUDGET, cfg.max_play)
    outcome = fx_attempt_safe(ctx)
    if outcome.ok:
        return Tally(0, True)
    fx_emit("step_error", idx, query, reason=outcome.reason, attempt=number)
    streak = tally.streak + 1
    fx_sleep(backoff_delay(streak))
    return Tally(streak, False)


def fx_do_song(cfg, count, run, item):
    if run.abort:
        return dataclasses.replace(run, stop=True)
    idx, query = item
    fx_emit("song_assigned", idx, query)
    tally = functools.reduce(partial(fx_try_attempt, cfg, idx, query),
                             range(1, MAX_ATTEMPTS + 1), Tally(run.streak, False))
    fails = 0 if tally.done else run.song_fails + 1
    return Run(tally.streak, fails, fails >= count, False)


def main(argv):
    cfg = parse_config(argv)
    if cfg.songs_path is None:
        return 2
    songs = fx_read_songs(cfg.songs_path)
    if not songs:
        return 2
    states = itertools.accumulate(
        song_stream(songs, cfg.start, cfg.max_songs),
        partial(fx_do_song, cfg, len(songs)),
        initial=Run(0, 0, False, False),
    )
    final = functools.reduce(lambda _, s: s, itertools.takewhile(lambda r: not r.stop, states),
                             Run(0, 0, False, False))
    return 1 if final.abort else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

"""Plays a list of YouTube songs in an already-open Chrome through the accessibility CLI."""
import argparse
import functools
import itertools
import json
import os
import re
import subprocess
import sys
import time
import xml.etree.ElementTree as ET
from collections import deque
from dataclasses import dataclass, replace
from typing import NamedTuple

# ---------------------------------------------------------------- helpers

apply_to = lambda acc, fn: fn(acc)
pipe = lambda value, *fns: functools.reduce(apply_to, fns, value)
compose = lambda *fns: lambda value: functools.reduce(apply_to, reversed(fns), value)
first = lambda items: next(iter(items), None)
norm = lambda text: " ".join(text.lower().split())
tokens = lambda text: frozenset(re.findall(r"\w+", text.lower()))
backoff = lambda failures: min(60.0, 5.0 * 2 ** max(0, failures - 1))
pause_deadline = lambda start, duration: start + duration - 3.0 - 0.6

AD_TITLES = frozenset({"Sponsored", "My Ad Center", "Skip", "Skip Ad", "Skip Ads"})
BAD_WORDS = re.compile(r"\b(mix|playlist|live|loop|radio|shorts?|hours?|24/7)\b", re.IGNORECASE)
SEEK = re.compile(
    r"(?:(\d+) Hours? )?(?:(\d+) Minutes? )?(\d+) Seconds? of "
    r"(?:(\d+) Hours? )?(?:(\d+) Minutes? )?(\d+) Seconds?",
    re.IGNORECASE,
)
LENGTH_TAIL = re.compile(r"((?:\d+ (?:hours?|minutes?|seconds?),? ?)+)\s*$")
PAUSE_TITLE = re.compile(r"Pause( \(k\)| keyboard shortcut k)?$")
PLAY_TITLE = re.compile(r"Play( \(k\)| keyboard shortcut k)$")


# ---------------------------------------------------------------- data

class Elem(NamedTuple):
    path: str
    title: str
    ident: str
    desc: str
    value: str
    enabled: bool
    frame: tuple


class Result(NamedTuple):
    code: int
    out: str
    err: str


class Reading(NamedTuple):
    pos: int
    dur: int
    t: float


class Cand(NamedTuple):
    path: str
    desc: str
    length: int | None
    score: int


class Status(NamedTuple):
    ad: bool
    skip: Elem | None
    pause: Elem | None
    play: Elem | None


class Opened(NamedTuple):
    reason: str | None
    length: int | None


class Outcome(NamedTuple):
    ok: bool
    reason: str


class SongState(NamedTuple):
    ok: bool
    fails: int


class Run(NamedTuple):
    fails: int
    streak: int
    successes: int
    processed: int
    stop: bool


@dataclass(frozen=True)
class Env:
    pid: str
    events: str
    max_play: float | None


@dataclass(frozen=True)
class Ctx:
    env: Env
    idx: int
    song: str


@dataclass(frozen=True)
class PollState:
    player: Elem | None = None
    in_ad: bool = False
    last_ad: float | None = None
    clean_since: float | None = None
    prev: Reading | None = None
    result: Reading | None = None
    failed: str | None = None


# ---------------------------------------------------------------- pure parsing

def parse_frame(text):
    nums = tuple(map(int, re.findall(r"-?\d+", text or "")))
    return nums[:4] if len(nums) >= 4 else ()


def to_elem(node):
    a = node.attrib
    return Elem(
        a.get("path", ""),
        a.get("title", ""),
        a.get("id", ""),
        a.get("description", ""),
        a.get("value", ""),
        a.get("enabled", "true") != "false",
        parse_frame(a.get("frame", "")),
    )


def parse_elems(text):
    try:
        root = ET.fromstring(text.strip())
    except ET.ParseError:
        return ()
    return tuple(map(to_elem, list(root)))


def json_field(text, key):
    try:
        data = json.loads(text)
    except ValueError:
        return None
    return data.get(key) if isinstance(data, dict) else None


def parse_seek(text):
    m = SEEK.search(text or "")
    if m is None:
        return None
    g = tuple(map(lambda x: int(x or 0), m.groups()))
    return (g[0] * 3600 + g[1] * 60 + g[2], g[3] * 3600 + g[4] * 60 + g[5])


def unit_seconds(unit):
    return 3600 if unit == "hour" else 60 if unit == "minute" else 1


def parse_length(title):
    m = LENGTH_TAIL.search(title)
    if m is None:
        return None
    parts = re.findall(r"(\d+) (hour|minute|second)", m.group(1))
    return sum(map(lambda p: int(p[0]) * unit_seconds(p[1]), parts))


keep_line = lambda line: bool(line) and not line.startswith("#")
parse_songs = compose(tuple, functools.partial(filter, keep_line),
                      functools.partial(map, str.strip), str.splitlines)

derive_box = lambda path: path[:-2] + ".0.0.0" if path.endswith(".1") else None


def hover_point(player):
    f = player.frame
    return (f[0] + f[2] // 2, f[1] + f[3] // 2) if len(f) == 4 else (597, 540)


# ---------------------------------------------------------------- pure decisions

is_ad_marker = lambda e: e.title in AD_TITLES
is_skip = lambda e: e.ident.startswith("skip-button") and e.enabled
is_pause = lambda e: PAUSE_TITLE.match(e.title) is not None
is_play = lambda e: PLAY_TITLE.match(e.title) is not None
is_video_link = lambda e: (e.ident == "video-title"
                           and e.value.startswith("https://www.youtube.com/watch")
                           and "/shorts/" not in e.value)
is_done = lambda s: s.result is not None or s.failed is not None


def classify(elems):
    return Status(
        any(map(is_ad_marker, elems)),
        first(filter(is_skip, elems)),
        first(filter(is_pause, elems)),
        first(filter(is_play, elems)),
    )


def to_cand(query_tokens, elem):
    desc = elem.desc or elem.title
    return Cand(elem.path, desc, parse_length(elem.title), len(query_tokens & tokens(desc)))


def is_good(query_tokens, cand):
    return (cand.length is not None
            and 45 <= cand.length <= 1500
            and BAD_WORDS.search(cand.desc) is None
            and (cand.score > 0 or not query_tokens))


def choose(elems, query):
    q = tokens(query)
    return pipe(
        elems,
        functools.partial(filter, is_video_link),
        functools.partial(map, functools.partial(to_cand, q)),
        functools.partial(filter, functools.partial(is_good, q)),
        functools.partial(sorted, key=lambda c: -c.score),
        tuple,
    )


def ad_length(reading, expected):
    return reading.dur < 60 or (expected is not None and abs(reading.dur - expected) > 5)


def believed(reading, anchor):
    start = reading.t - reading.pos
    return anchor - 10.0 <= start <= anchor + 60.0


def consistent(prev, reading):
    return (prev is not None
            and reading.t - prev.t >= 2.5
            and abs((reading.t - reading.pos) - (prev.t - prev.pos)) <= 1.5)


def resync_start(start, duration, reading):
    implied = reading.t - reading.pos
    return implied if abs(reading.dur - duration) <= 3 and abs(implied - start) <= 10.0 else start


# ---------------------------------------------------------------- effects

def now():
    return time.time()


def mono():
    return time.monotonic()


def nap(seconds):
    time.sleep(max(0.0, seconds))


def nap_until(moment):
    nap(moment - mono())


def run_b4(pid, cmd):
    prefix = json.loads(os.environ["YUO_B4"])
    args = [*cmd, "--pid", pid]
    try:
        done = subprocess.run([*prefix, *args], capture_output=True, timeout=90)
    except subprocess.TimeoutExpired:
        return Result(124, "", "timeout")
    except OSError:
        return Result(127, "", "os error")
    return Result(done.returncode,
                  done.stdout.decode("utf-8", errors="replace"),
                  done.stderr.decode("utf-8", errors="replace"))


def b4(ctx, *cmd):
    return run_b4(ctx.env.pid, list(cmd))


def find(ctx, *opts):
    res = b4(ctx, "find", *opts, "--format", "xml")
    return parse_elems(res.out) if res.code == 0 else None


def emit(ctx, kind, **extra):
    record = {"t": now(), "stage": "exploitation", "source": "solution", "kind": kind,
              "song_index": ctx.idx, "song": ctx.song, **extra}
    with open(ctx.env.events, "a", encoding="utf-8") as fh:
        fh.write(json.dumps(record, ensure_ascii=False) + "\n")


def poll(probe, interval, limit):
    ticks = itertools.takewhile(lambda _: mono() < limit, itertools.count())
    return next(filter(None, map(lambda _: probe() or nap(interval), ticks)), None)


def find_player(ctx):
    return first(find(ctx, "--identifier", "movie_player", "--depth", "40", "--limit", "1") or ())


def scan(ctx, player):
    return find(ctx, "--under", player.path, "--depth", "5", "--limit", "80")


def find_pause(ctx, player):
    scope = ("--under", player.path) if player is not None else ()
    found = find(ctx, *scope, "--title", "Pause", "--limit", "1") or ()
    return first(filter(is_pause, found))


def hover_player(ctx, player):
    x, y = hover_point(player)
    b4(ctx, "activate")
    tuple(map(lambda px: b4(ctx, "hover", "--x", str(px), "--y", str(y)), (x - 40, x)))
    nap(0.8)


def read_seek(ctx, player):
    hover_player(ctx, player)
    t0 = mono()
    found = find(ctx, "--title", "Seek slider", "--role", "AXSlider",
                 "--under", player.path, "--depth", "6", "--limit", "1")
    t1 = mono()
    parsed = parse_seek(found[0].value) if found else None
    return None if parsed is None else Reading(parsed[0], parsed[1], (t0 + t1) / 2.0)


# ---------------------------------------------------------------- search and open

def type_query(ctx, button):
    box = derive_box(button.path)
    if box is not None and b4(ctx, "set-value", "--path", box, "--value", ctx.song,
                              "--expect-description", "Search").code == 0:
        return True
    combos = find(ctx, "--role", "combobox", "--title", "Search", "--depth", "40", "--limit", "4") or ()
    combo = first(filter(lambda e: e.title == "Search", combos))
    return combo is not None and b4(ctx, "set-value", "--path", combo.path, "--value", ctx.song,
                                    "--expect-description", "Search").code == 0


def title_ready(ctx):
    title = json_field(b4(ctx, "inspect", "--path", "0.1").out, "title")
    return isinstance(title, str) and norm(ctx.song) in norm(title)


def candidates(ctx):
    elems = find(ctx, "--role", "link", "--identifier", "video-title", "--depth", "40", "--limit", "20")
    return choose(elems or (), ctx.song) or None


def open_result(ctx, limit):
    buttons = find(ctx, "--role", "button", "--title", "Search", "--depth", "40", "--limit", "8") or ()
    button = first(filter(lambda e: e.title == "Search", buttons))
    if button is None:
        return Opened("search button not found", None)
    if not type_query(ctx, button):
        return Opened("could not enter the query", None)
    submitted = b4(ctx, "press", "--path", button.path, "--expect-description", "Search")
    if submitted.code != 0:
        return Opened("search press failed with exit " + str(submitted.code), None)
    nap(2.0)
    poll(lambda: title_ready(ctx), 1.0, min(limit, mono() + 12.0))
    cands = poll(lambda: candidates(ctx), 1.5, min(limit, mono() + 12.0))
    if not cands:
        return Opened("no suitable search result", None)
    pressed = map(lambda c: (c, b4(ctx, "press", "--path", c.path, "--expect-description", c.desc)),
                  cands[:4])
    chosen = next(filter(lambda pr: pr[1].code == 0, pressed), None)
    if chosen is None:
        return Opened("no search result could be opened", None)
    return Opened(None, chosen[0].length)


# ---------------------------------------------------------------- waiting for the song

def on_ad(ctx, st, status):
    if not st.in_ad:
        emit(ctx, "ad_seen")
    if status.skip is not None:
        b4(ctx, "press", "--path", status.skip.path, "--expect-description", "Skip")
    nap(0.5)
    return replace(st, in_ad=True, last_ad=mono(), clean_since=None, prev=None)


def on_play(ctx, st, status):
    b4(ctx, "press", "--path", status.play.path, "--expect-description", status.play.title)
    nap(1.0)
    return replace(st, in_ad=False)


def on_clean(ctx, expected, st):
    clean = mono() if st.clean_since is None else st.clean_since
    seen = replace(st, in_ad=False, clean_since=clean)
    reading = read_seek(ctx, st.player)
    if reading is None:
        nap(1.0)
        return seen
    if ad_length(reading, expected):
        nap(1.0)
        return replace(seen, last_ad=reading.t, prev=None)
    anchor = clean if st.last_ad is None else st.last_ad
    if believed(reading, anchor) or consistent(st.prev, reading):
        return replace(seen, result=reading)
    nap(2.0)
    return replace(seen, prev=reading)


def poll_tick(ctx, expected, deadline, st):
    if mono() > deadline:
        return replace(st, failed="timed out waiting for the song to play")
    player = st.player or find_player(ctx)
    if player is None:
        nap(1.0)
        return st
    elems = scan(ctx, player)
    if elems is None:
        nap(1.0)
        return replace(st, player=None)
    status = classify(elems)
    known = replace(st, player=player)
    if status.ad:
        return on_ad(ctx, known, status)
    if status.play is not None and status.pause is None:
        return on_play(ctx, known, status)
    if status.pause is not None:
        return on_clean(ctx, expected, known)
    nap(1.0)
    return known


def wait_for_playback(ctx, expected, deadline):
    advance = lambda st, _: poll_tick(ctx, expected, deadline, st)
    states = itertools.accumulate(itertools.repeat(None), advance, initial=PollState())
    return next(itertools.dropwhile(lambda s: not is_done(s), states))


# ---------------------------------------------------------------- pausing

def try_press(ctx, pause):
    return pause is not None and b4(ctx, "press", "--path", pause.path,
                                    "--expect-description", pause.title).code == 0


def refind_pause(ctx, player):
    nap(0.5)
    return find_pause(ctx, find_player(ctx) or player)


def press_pause(ctx, player, remembered):
    sources = (lambda: remembered,
               lambda: refind_pause(ctx, player),
               lambda: refind_pause(ctx, player))
    return next(filter(None, map(lambda src: try_press(ctx, src()), sources)), False)


def pause_at_end(ctx, player0, reading, started):
    duration = reading.dur
    start0 = reading.t - reading.pos
    natural = pause_deadline(start0, duration)
    cap = None if ctx.env.max_play is None else started + ctx.env.max_play
    capped = cap is not None and cap < natural
    deadline0 = cap if capped else natural
    nap_until(deadline0 - 15.0)
    player = find_player(ctx) or player0
    remembered = find_pause(ctx, player)
    resync = None if capped or player is None or mono() > deadline0 - 4.0 else read_seek(ctx, player)
    start = start0 if resync is None else resync_start(start0, duration, resync)
    deadline = deadline0 if capped else pause_deadline(start, duration)
    nap_until(deadline)
    ok = press_pause(ctx, player, remembered)
    if ok:
        emit(ctx, "paused", duration=duration, remaining=round(start + duration - mono(), 2))
    return ok


# ---------------------------------------------------------------- song loop

def attempt(ctx):
    limit = mono() + 120.0
    opened = open_result(ctx, limit)
    if opened.reason is not None:
        return Outcome(False, opened.reason)
    final = wait_for_playback(ctx, opened.length, limit)
    if final.failed is not None:
        return Outcome(False, final.failed)
    reading = final.result
    started = mono()
    emit(ctx, "playback_started", position=round(reading.pos + (started - reading.t), 1))
    paused = pause_at_end(ctx, final.player, reading, started)
    return Outcome(paused, "ok" if paused else "pause control could not be pressed")


def safe_attempt(ctx):
    try:
        return attempt(ctx)
    except Exception as exc:
        return Outcome(False, "unexpected error: " + repr(exc))


def run_attempt(ctx, state, _n):
    if state.ok:
        return state
    outcome = safe_attempt(ctx)
    if outcome.ok:
        return SongState(True, 0)
    emit(ctx, "step_error", reason=outcome.reason)
    nap(backoff(state.fails + 1))
    return SongState(False, state.fails + 1)


def play_song(env, fails, item):
    ctx = Ctx(env, item[0], item[1])
    emit(ctx, "song_assigned")
    return functools.reduce(functools.partial(run_attempt, ctx), range(3), SongState(False, fails))


def step(env, total, run, item):
    done = play_song(env, run.fails, item)
    streak = 0 if done.ok else run.streak + 1
    return Run(done.fails, streak, run.successes + int(done.ok), run.processed + 1, streak >= total)


def stop_after(pred, items):
    for item in items:
        yield item
        if pred(item):
            return


def parse_args(argv):
    p = argparse.ArgumentParser()
    p.add_argument("--songs", required=True)
    p.add_argument("--max-songs", type=int, default=None)
    p.add_argument("--forever", action="store_true")
    p.add_argument("--start-index", type=int, default=0)
    p.add_argument("--max-play-seconds", type=float, default=None)
    return p.parse_args(argv)


def main():
    args = parse_args(sys.argv[1:])
    with open(args.songs, encoding="utf-8-sig") as fh:
        songs = parse_songs(fh.read())
    if not songs:
        print("no songs in " + args.songs, file=sys.stderr)
        return 2
    env = Env(os.environ["YUO_CHROME_PID"], os.environ["YUO_EVENTS"], args.max_play_seconds)
    order = itertools.islice(itertools.cycle(enumerate(songs)), args.start_index % len(songs), None)
    limited = order if args.forever or args.max_songs is None else itertools.islice(order, args.max_songs)
    states = itertools.accumulate(limited, functools.partial(step, env, len(songs)),
                                  initial=Run(0, 0, 0, 0, False))
    final = deque(stop_after(lambda r: r.stop, states), maxlen=1)[0]
    return 1 if final.stop or (final.processed > 0 and final.successes == 0) else 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Play a list of YouTube songs in an already-open Chrome through the accessibility CLI.

Functional style: pure parsing/decision functions, a small set of effect functions
(run_b4, call, emit, nap, now, tick, ...), immutable data only.
"""
import argparse
import concurrent.futures
import itertools
import json
import math
import os
import re
import subprocess
import sys
import time
import xml.etree.ElementTree as ET
from functools import partial, reduce
from itertools import accumulate, chain, cycle, islice, repeat, takewhile
from typing import NamedTuple, Optional

# ----------------------------------------------------------------------------
# constants
# ----------------------------------------------------------------------------
ATTEMPT_SECONDS = 120.0
MAX_ATTEMPTS = 3
END_MARGIN = 3.0
PRESS_LATENCY = 0.6
RESYNC_LEAD = 15.0
RESYNC_MIN_LEFT = 6.0
HOVER_SETTLE = 0.8
RESULT_WAIT = 2.5
POST_PRESS_WAIT = 3.0
MIN_SONG_SECONDS = 60
MAX_SONG_SECONDS = 1200
DURATION_SLACK = 6
MAX_TRIES = 4
AD_TITLES = frozenset(("Sponsored", "My Ad Center", "Skip", "Skip Ad", "Skip Ads"))
PROBE_TITLES = ("Skip", "Sponsored", "My Ad Center", "Pause", "Play")
BAD_WORDS = frozenset((
    "mix", "playlist", "live", "loop", "looped", "hour", "hours", "radio", "shorts",
    "stream", "reaction", "cover", "karaoke", "remix", "instrumental", "slowed",
    "reverb", "nightcore"))
UNIT_SECONDS = (("hour", 3600), ("minute", 60), ("second", 1))
DURATION_TAIL = re.compile(r"((?:\d+\s+(?:hours?|minutes?|seconds?)(?:,\s*)?)+)\s*$")


# ----------------------------------------------------------------------------
# data
# ----------------------------------------------------------------------------
class Cmd(NamedTuple):
    code: int
    out: str
    err: str


class Config(NamedTuple):
    songs: tuple
    max_play: Optional[float]


class Ctx(NamedTuple):
    idx: int
    song: str
    max_play: Optional[float]
    expected: Optional[int] = None


class Control(NamedTuple):
    path: str
    desc: str
    title: str
    ident: str
    enabled: bool


class Probe(NamedTuple):
    player: Optional[str]
    center: Optional[tuple]
    ad: bool
    skip: Optional[str]
    pause: Optional[Control]
    play: Optional[Control]


class Candidate(NamedTuple):
    path: str
    desc: str
    duration: Optional[int]
    value: str


class Reading(NamedTuple):
    pos: int
    dur: int
    t: float


class Watch(NamedTuple):
    t0: float
    in_ad: bool = False
    last_ad: Optional[float] = None
    clean_since: Optional[float] = None
    play_streak: int = 0
    start: Optional[float] = None
    duration: Optional[int] = None
    position: Optional[int] = None
    t_started: Optional[float] = None
    done: bool = False
    reason: Optional[str] = None


class Outcome(NamedTuple):
    ok: bool
    reason: str = ""


class Tally(NamedTuple):
    ok: bool
    streak: int


class RunState(NamedTuple):
    n: int = 0
    oks: int = 0
    streak: int = 0
    consec: int = 0
    fatal: bool = False
    halted: bool = False


NO_PLAYER = Probe(None, None, False, None, None, None)


# ----------------------------------------------------------------------------
# pure helpers
# ----------------------------------------------------------------------------
def compose(*fns):
    return reduce(lambda f, g: (lambda x: f(g(x))), fns)


def pipe(value, *fns):
    return reduce(lambda acc, f: f(acc), fns, value)


def first_where(pred, items):
    return next(filter(pred, items), None)


tokens = compose(frozenset, partial(re.findall, r"\w+"), str.lower)
is_song_line = lambda line: line != "" and not line.startswith("#")
parse_songs = lambda text: pipe(
    text, str.splitlines, partial(map, str.strip), partial(filter, is_song_line), tuple)


def parse_json(text):
    try:
        return json.loads(text)
    except ValueError:
        return None


def matches_of(cmd):
    data = parse_json(cmd.out) if cmd.code == 0 else None
    found = data.get("matches") if isinstance(data, dict) else None
    return tuple(found) if isinstance(found, list) else ()


def find_args(title=None, role=None, identifier=None, under=None, depth=None, limit=None, fmt=None):
    pairs = (("--title", title), ("--role", role), ("--identifier", identifier),
             ("--under", under), ("--depth", depth), ("--limit", limit), ("--format", fmt))
    return ("find",) + tuple(chain.from_iterable(
        (key, str(val)) for key, val in pairs if val is not None))


def parse_span(text):
    parts = re.findall(r"(\d+)\s*(hour|minute|second)", text.lower())
    scale = dict(UNIT_SECONDS)
    return reduce(lambda acc, p: acc + int(p[0]) * scale[p[1]], parts, 0) if parts else None


def parse_seek(text):
    halves = text.split(" of ") if isinstance(text, str) else ()
    both = tuple(map(parse_span, halves))
    return (both[0], both[1]) if len(both) == 2 and None not in both else None


def duration_of(title):
    found = DURATION_TAIL.search(title)
    return parse_span(found.group(1)) if found else None


def frame_center(frame):
    nums = tuple(map(int, re.findall(r"-?\d+", frame or "")))
    return (nums[0] + nums[2] // 2, nums[1] + nums[3] // 2) if len(nums) == 4 else None


def parse_player(text):
    try:
        root = ET.fromstring(text)
    except ET.ParseError:
        return None
    first = next(iter(root), None)
    path = first.get("path") if first is not None else None
    return (path, frame_center(first.get("frame"))) if path else None


def derive_box(button_path):
    return button_path[:-2] + ".0.0" if button_path.endswith(".1") else None


def as_control(m):
    title = str(m.get("title") or "")
    return Control(str(m.get("path") or ""), str(m.get("description") or title), title,
                   str(m.get("identifier") or ""), m.get("enabled") is not False)


is_pause = lambda c: c.title.startswith("Pause")
is_play = lambda c: c.title.startswith("Play") and (
    c.title.endswith("(k)") or c.title.endswith("shortcut k"))
is_skip_button = lambda c: c.ident.startswith("skip-button") and c.enabled


def summarize(player, center, groups):
    flat = tuple(map(as_control, chain.from_iterable(groups)))
    skip = first_where(is_skip_button, flat)
    return Probe(
        player, center,
        any(c.title in AD_TITLES for c in flat),
        skip.path if skip is not None else None,
        first_where(is_pause, flat),
        first_where(is_play, flat))


def to_candidate(m):
    title = str(m.get("title") or "")
    return Candidate(str(m.get("path") or ""), str(m.get("description") or title),
                     duration_of(title), str(m.get("value") or ""))


def is_video(c):
    return c.path != "" and c.value.startswith("https://www.youtube.com/watch") \
        and "/shorts/" not in c.value


def is_clean(qt, c):
    return not (tokens(c.desc) & (BAD_WORDS - qt)) and c.duration is not None \
        and MIN_SONG_SECONDS <= c.duration <= MAX_SONG_SECONDS


def rank_candidates(query, matches):
    qt = tokens(query)
    need = max(1, len(qt) // 2)
    score = lambda c: len(qt & tokens(c.desc))
    pool = tuple(filter(partial(is_clean, qt), filter(is_video, map(to_candidate, matches))))
    ordered = sorted(pool, key=lambda c: -score(c))
    return tuple(islice(filter(lambda c: score(c) >= need, ordered), MAX_TRIES))


def backoff_seconds(streak):
    return float(min(60, 5 * 2 ** max(0, streak - 1)))


def observe(w, pr, t):
    playing_clean = (not pr.ad) and pr.pause is not None
    kept = w.clean_since if w.clean_since is not None else (t if playing_clean else None)
    return w._replace(
        in_ad=pr.ad,
        last_ad=t if pr.ad else w.last_ad,
        clean_since=None if pr.ad else kept,
        play_streak=w.play_streak + 1 if (pr.play is not None and pr.pause is None and not pr.ad) else 0)


def plausible_start(w, start):
    if w.clean_since is None or start > w.clean_since + 60.0:
        return False
    return start >= w.last_ad - 3.0 if w.last_ad is not None else start >= w.clean_since - 10.0


def judge(w, rd, expected):
    if rd is None:
        return w
    mismatch = rd.dur < MIN_SONG_SECONDS or (
        expected is not None and abs(rd.dur - expected) > DURATION_SLACK)
    if mismatch:
        return w._replace(last_ad=rd.t, clean_since=None)
    start = rd.t - rd.pos
    if plausible_start(w, start):
        return w._replace(start=start, duration=rd.dur, position=rd.pos,
                          t_started=rd.t, done=True)
    return w


def resync_start(w, rd):
    if rd is None or abs(rd.dur - w.duration) > 3:
        return w.start
    new = rd.t - rd.pos
    agree = abs(new - w.start) <= 10.0
    earlier = new < w.start - 10.0 and plausible_start(w, new)
    return new if (agree or earlier) else w.start


# ----------------------------------------------------------------------------
# effects
# ----------------------------------------------------------------------------
def now():
    return time.time()


def tick():
    return time.monotonic()


def nap(seconds):
    time.sleep(max(0.0, seconds))


def nap_until(wall):
    nap(wall - now())


def read_text(path):
    with open(path, "r", encoding="utf-8-sig") as fh:
        return fh.read()


def emit(idx, song, kind, **extra):
    record = {"t": time.time(), "stage": "exploitation", "source": "solution",
              "kind": kind, "song_index": idx, "song": song, **extra}
    with open(os.environ["YUO_EVENTS"], "a", encoding="utf-8") as fh:
        fh.write(json.dumps(record, ensure_ascii=False) + "\n")


def run_b4(args, timeout=60.0):
    prefix = json.loads(os.environ["YUO_B4"])
    try:
        done = subprocess.run([*prefix, *args], capture_output=True, timeout=timeout)
    except (subprocess.TimeoutExpired, OSError):
        return Cmd(124, "", "timeout")
    return Cmd(done.returncode, done.stdout.decode("utf-8", "replace"),
               done.stderr.decode("utf-8", "replace"))


def call(*args):
    return run_b4((*args, "--pid", os.environ["YUO_CHROME_PID"]))


def press_ok(path, description):
    return call("press", "--path", path, "--expect-description", description).code == 0


def locate_player():
    return parse_player(call(*find_args(identifier="movie_player", depth=40, limit=1, fmt="xml")).out)


def find_pause(player):
    found = matches_of(call(*find_args(title="Pause", under=player, depth=6, limit=1)))
    return first_where(is_pause, map(as_control, found))


def probe_player():
    located = locate_player()
    if located is None:
        return NO_PLAYER
    path, center = located
    fetch = lambda title: matches_of(call(*find_args(title=title, under=path, depth=6, limit=10)))
    with concurrent.futures.ThreadPoolExecutor(max_workers=len(PROBE_TITLES)) as pool:
        groups = tuple(pool.map(fetch, PROBE_TITLES))
    return summarize(path, center, groups)


def read_position(player, center):
    call("activate")
    if center is not None:
        call("hover", "--x", str(center[0] - 40), "--y", str(center[1]))
        call("hover", "--x", str(center[0]), "--y", str(center[1]))
    nap(HOVER_SETTLE)
    t_a = now()
    found = matches_of(call(*find_args(title="Seek slider", role="slider", under=player,
                                       depth=6, limit=1)))
    t_b = now()
    parsed = parse_seek(found[0].get("value")) if found else None
    return None if parsed is None else Reading(parsed[0], parsed[1], (t_a + t_b) / 2.0)


def submit_search(query):
    """Type the query and press the exact 'Search' button; return an error text or None."""
    buttons = matches_of(call(*find_args(title="Search", role="button", depth=40, limit=8)))
    button = first_where(lambda m: m.get("title") == "Search", buttons)
    combos = matches_of(call(*find_args(title="Search", role="combobox", depth=40, limit=4)))
    combo = first_where(lambda m: m.get("title") == "Search", combos)
    box = combo.get("path") if combo else (derive_box(button.get("path", "")) if button else None)
    if button is None or not box:
        return "search box or button not found"
    if call("set-value", "--path", box, "--value", query, "--expect-description", "Search").code != 0:
        return "could not set the search text"
    if not press_ok(button.get("path"), "Search"):
        return "could not press the Search button"
    return None


def fetch_results(query, attempt_no):
    nap(RESULT_WAIT if attempt_no == 0 else 2.0)
    return rank_candidates(query, matches_of(call(*find_args(
        role="link", identifier="video-title", depth=40, limit=25))))


def press_first_ok(cands):
    return first_where(lambda c: press_ok(c.path, c.desc), cands)


def open_song(ctx):
    problem = submit_search(ctx.song)
    if problem is not None:
        return None, problem
    cands = next(filter(None, map(partial(fetch_results, ctx.song), range(3))), ())
    if not cands:
        return None, "no suitable search result"
    opened = press_first_ok(cands)
    return (opened, "") if opened is not None else (None, "no result could be opened")


def press_pause(pause):
    first = pause is not None and press_ok(pause.path, "Pause (k)")
    if first:
        return True
    located = locate_player()
    again = find_pause(located[0]) if located is not None else None
    return again is not None and press_ok(again.path, again.desc)


def resync(w, deadline):
    located = locate_player()
    pause = find_pause(located[0]) if located is not None else None
    can_read = located is not None and deadline - now() > RESYNC_MIN_LEFT
    rd = read_position(*located) if can_read else None
    return pause, resync_start(w, rd)


def watch_step(ctx, w, _):
    if tick() - w.t0 > ATTEMPT_SECONDS:
        return w._replace(done=True, reason="song not confirmed playing within the time budget")
    pr = probe_player()
    w1 = observe(w, pr, now())
    if pr.ad and not w.in_ad:
        emit(ctx.idx, ctx.song, "ad_seen", skippable=pr.skip is not None)
    if pr.player is None:
        nap(1.0)
        return w1
    if pr.ad:
        if pr.skip is not None:
            press_ok(pr.skip, "Skip")
            nap(0.5)
        else:
            nap(0.7)
        return w1
    if pr.pause is not None:
        return judge(w1, read_position(pr.player, pr.center), ctx.expected)
    if pr.play is not None and w1.play_streak >= 2:
        press_ok(pr.play.path, pr.play.desc)
        nap(1.0)
        return w1._replace(play_streak=0)
    nap(1.0)
    return w1


def pause_phase(ctx, w):
    cap = w.t_started + ctx.max_play if ctx.max_play is not None else math.inf
    deadline_for = lambda start: min(start + w.duration - END_MARGIN - PRESS_LATENCY, cap)
    first_deadline = deadline_for(w.start)
    nap_until(first_deadline - RESYNC_LEAD)
    pause, start = resync(w, first_deadline)
    nap_until(deadline_for(start))
    pressed = press_pause(pause)
    t = now()
    if not pressed:
        return Outcome(False, "pause control could not be pressed")
    emit(ctx.idx, ctx.song, "paused", duration=w.duration,
         remaining=round(start + w.duration - t, 3))
    return Outcome(True)


def run_attempt(ctx):
    t0 = tick()
    cand, why = open_song(ctx)
    if cand is None:
        return Outcome(False, why)
    ctx2 = ctx._replace(expected=cand.duration)
    nap(POST_PRESS_WAIT)
    states = accumulate(repeat(None), partial(watch_step, ctx2), initial=Watch(t0=t0))
    w = next(filter(lambda s: s.done, states))
    if w.start is None:
        return Outcome(False, w.reason or "playback not confirmed")
    emit(ctx.idx, ctx.song, "playback_started", position=w.position)
    return pause_phase(ctx2, w)


def guarded(ctx):
    try:
        return run_attempt(ctx)
    except Exception as exc:
        return Outcome(False, f"unexpected error: {exc!r}")


def attempt_step(cfg, idx, song, tally, number):
    if tally.ok:
        return tally
    outcome = guarded(Ctx(idx, song, cfg.max_play))
    if outcome.ok:
        return Tally(True, 0)
    streak = tally.streak + 1
    emit(idx, song, "step_error", reason=outcome.reason, attempt=number + 1)
    nap(backoff_seconds(streak))
    return Tally(False, streak)


def play_song(cfg, idx, song, streak):
    emit(idx, song, "song_assigned")
    return reduce(partial(attempt_step, cfg, idx, song), range(MAX_ATTEMPTS), Tally(False, streak))


def song_step(cfg, st, item):
    if st.fatal:
        return st._replace(halted=True)
    idx, song = item
    tally = play_song(cfg, idx, song, st.streak)
    consec = 0 if tally.ok else st.consec + 1
    return st._replace(n=st.n + 1, oks=st.oks + (1 if tally.ok else 0), streak=tally.streak,
                       consec=consec, fatal=consec >= len(cfg.songs))


def parse_args(argv):
    parser = argparse.ArgumentParser()
    parser.add_argument("--songs", required=True)
    parser.add_argument("--max-songs", type=int, default=None)
    parser.add_argument("--forever", action="store_true")
    parser.add_argument("--start-index", type=int, default=0)
    parser.add_argument("--max-play-seconds", type=float, default=None)
    return parser.parse_args(argv)


def main(argv):
    args = parse_args(argv)
    songs = parse_songs(read_text(args.songs))
    if not songs:
        return 2
    cfg = Config(songs, args.max_play_seconds)
    seq = islice(cycle(tuple(enumerate(songs))), args.start_index % len(songs), None)
    limited = seq if args.max_songs is None else islice(seq, args.max_songs)
    states = accumulate(limited, partial(song_step, cfg), initial=RunState())
    final = reduce(lambda _, s: s, takewhile(lambda s: not s.halted, states))
    failed = final.fatal or (final.n > 0 and final.oks == 0)
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
